/* logInqyDao1020 : 로그 목록 조회 */ SELECT SUB_DATA.* FROM ( SELECT L.LOG_ID , L.LOGTYPE_CD , CC_LOG.COMMCODE_NM AS LOGTYPE_NM , L.EMP_IDX , E.EMP_ID , E.EMP_NM , O.ORG_NM , L.MAPPING_ID , L.IP_ADDR , L.IS_SUCC , L.LOG_MSG , L.REG_DT , L.REG_TM , L.USE_YN , L.DISP_ORDER , COUNT(L.LOG_ID) OVER() AS LIST_CNT , ROW_NUMBER() OVER(ORDER BY L.REG_DT DESC, L.REG_TM DESC) AS NUM FROM LOG L LEFT OUTER JOIN EMP_INFO E ON L.EMP_IDX = E.EMP_IDX LEFT OUTER JOIN ORG O ON O.ORG_CD = E.ORG_CD AND O.USE_YN = 'Y' LEFT OUTER JOIN RANK R ON R.RANK_CD = E.RANK_CD AND R.USE_YN = 'Y' LEFT OUTER JOIN COMMCODE CC_LOG ON CC_LOG.COMMCODE_CD = L.LOGTYPE_CD WHERE 1=1
AND REGEXP_REPLACE(LOWER(E.EMP_NM),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{srchNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
AND L.REG_DT >= REPLACE(#{srchSdt, jdbcType=VARCHAR},'-','')
AND L.REG_DT <= REPLACE(#{srchEdt, jdbcType=VARCHAR},'-','')
AND L.LOGTYPE_CD = #{srchLogCd, jdbcType=VARCHAR}
) SUB_DATA WHERE 1=1
AND SUB_DATA.NUM BETWEEN #{sIdx, jdbcType=VARCHAR} AND #{eIdx, jdbcType=VARCHAR}
ORDER BY SUB_DATA.NUM DESC

