/* logProcDao1010 : 로그 등록 처리 */
INSERT INTO LOG
(
		LOG_ID
	,	LOGTYPE_CD
	,	EMP_IDX
	,	MAPPING_ID
	,	IP_ADDR
	,	IS_SUCC
	,	LOG_MSG
	,	REG_DT
	,	REG_TM
	,	USE_YN
	,	DISP_ORDER
	,	REMARK
)
VALUES
(
		#{sequenceId, jdbcType=VARCHAR}
	,	#{logtypeCd, jdbcType=VARCHAR}
	,	#{empIdx, jdbcType=VARCHAR}
	,	#{mappingId, jdbcType=VARCHAR}
	,	#{ipAddr, jdbcType=VARCHAR}
	,	#{isSucc, jdbcType=VARCHAR}
	,	#{logMsg, jdbcType=VARCHAR}
	,	TO_CHAR(SYSDATE,'YYYYMMDD')
	,	TO_CHAR(SYSDATE,'HH24MISS')
	,	#{useYn, jdbcType=VARCHAR}
	,	(
			SELECT 
				NVL(MAX(DISP_ORDER),0) + 1 
			FROM LOG
		)
	,	NULL
	)
